static std::string extra(const mahoyo::save::Document& d){return {d.hostExtra.begin(),d.hostExtra.end()};}
static std::vector<int> activeIds(const mahoyo::save::Document& d){std::istringstream in(extra(d));std::string row;size_t n;std::getline(in,row);check(row=="WOHHOST23","actual coordinated writer21");in>>n;std::getline(in,row);for(size_t k=0;k<n;++k)std::getline(in,row);in>>n;std::getline(in,row);std::vector<int> ids;for(size_t k=0;k<n;++k){std::getline(in,row);ids.push_back(std::stoi(hostFields(row).at(0)));}return ids;}
static std::set<int> layerIds(const mahoyo::save::Document& d){std::set<int> ids;for(const auto& l:d.layers)ids.insert(l.id);return ids;}
static State footer(const mahoyo::save::Document& d){auto s=extra(d);auto at=s.find("\nEFFECTREGISTRY1 ");check(at!=std::string::npos,"complete20 suffix boundary");std::istringstream in(s.substr(at+1));auto v=mahoyo::host_state20::read(in,activeIds(d),layerIds(d));(void)mahoyo::language::readTextState(in,d.history.size());std::string more;check(!(in>>more),"complete20 suffix consumed");return v;}
static std::string encoded(const State& s,const mahoyo::save::Document& d){std::ostringstream out;mahoyo::host_state20::write(out,s,activeIds(d),layerIds(d));return out.str();}
static mahoyo::save::Document withFooter(mahoyo::save::Document d,const State& s){auto bytes=extra(d);auto at=bytes.find("\nEFFECTREGISTRY1 ");check(at!=std::string::npos,"20 replacement suffix");auto language=bytes.substr(bytes.find("LANGUAGETEXT1 "));bytes.resize(at+1);bytes+=encoded(s,d)+language;d.hostExtra.assign(bytes.begin(),bytes.end());return d;}
static std::string bytes(const fs::path& path){std::ifstream in(path,std::ios::binary);return {std::istreambuf_iterator<char>(in),std::istreambuf_iterator<char>()};}
static std::vector<std::string> rows(const std::string& s){std::istringstream in(s);std::vector<std::string> out;std::string row;while(std::getline(in,row))out.push_back(row);return out;}
static std::string field(std::string row,size_t at,const std::string& value){auto fields=hostFields(row);check(at<fields.size(),"20 negative field");fields[at]=value;std::string text;for(auto& f:fields){if(!text.empty())text+=' ';text+=f;}return text;}
